SELECT AVG(dragons) AS media_dragoes
FROM pro_games
WHERE year = 2026;

SELECT AVG(towers) AS media_torres_vencedoras
FROM pro_games
WHERE win;

SELECT AVG(barons) AS media_baoes_vencedoras
FROM pro_games
WHERE win;

SELECT AVG(a.gold_diff_at15) AS media_ouro_diff_15min
FROM pro_games a
WHERE a.win AND a.gold_diff_at15 IS NOT NULL;
